SQL:
SELECT COUNT(DISTINCT demand_id)
FROM fact_consigner_demands_lead_source
WHERE trip_flag = 1;

SELECT COUNT(DISTINCT operator_code)
FROM fact_operators_mp_events
WHERE landed_on_mp = 1;

SELECT COUNT(DISTINCT operator_code)
FROM analytics.fact_operators_onb
WHERE sub_date BETWEEN :start_date AND :end_date;
